# Library: https://github.com/tyuyu-62/cp-library
"""Kruskal reconstruction tree for threshold connectivity queries."""


class KruskalReconstructionTree:
    """Build the merge tree generated by weighted undirected edges.

    Time:
        O(N + M log M) construction and O(1) connectivity queries.

    Space:
        O(N + M).
    """

    __slots__ = (
        "n",
        "parent",
        "weight",
        "roots",
        "_leader",
        "_component_root",
    )

    def __init__(self, n: int, edges, maximum: bool = False) -> None:
        self.n = n
        parent = [-1] * n
        weight = [None] * n
        leader = list(range(n))
        size = [1] * n
        next_node = n
        ordered = sorted(edges, key=lambda edge: edge[2], reverse=maximum)

        def find(vertex: int) -> int:
            while leader[vertex] != vertex:
                leader[vertex] = leader[leader[vertex]]
                vertex = leader[vertex]
            return vertex

        for u, v, edge_weight in ordered:
            left = find(u)
            right = find(v)
            if left == right:
                continue
            if size[left] < size[right]:
                left, right = right, left
            node = next_node
            next_node += 1
            parent.append(-1)
            weight.append(edge_weight)
            parent[left] = node
            parent[right] = node
            leader[left] = node
            leader[right] = node
            leader.append(node)
            size.append(size[left] + size[right])
        roots = [node for node in range(next_node) if parent[node] == -1]
        component_root = [0] * n
        vertex = 0
        while vertex < n:
            component_root[vertex] = find(vertex)
            vertex += 1
        self.parent = parent
        self.weight = weight
        self.roots = roots
        self._leader = leader
        self._component_root = component_root

    def component_root(self, vertex: int) -> int:
        """Return the reconstruction-tree root containing vertex in O(1)."""
        return self._component_root[vertex]

    def connected(self, first: int, second: int) -> bool:
        """Return whether two leaves belong to the same component in O(1)."""
        component_root = self._component_root
        return component_root[first] == component_root[second]
